INSERT INTO `pages` VALUES (103,1,'About Us','about','		<div data-elementor-type=\"wp-page\" data-elementor-id=\"4474\" class=\"elementor elementor-4474\">\n				<div class=\"elementor-element elementor-element-c28a45c e-flex e-con-boxed wpr-particle-no wpr-jarallax-no wpr-parallax-no wpr-sticky-section-no wpr-column-slider-no wpr-equal-height-no e-con e-parent\" data-id=\"c28a45c\" data-element_type=\"container\" data-e-type=\"container\">\n					<div class=\"e-con-inner\">\n		<div class=\"elementor-element elementor-element-e265448 e-con-full e-flex wpr-particle-no wpr-jarallax-no wpr-parallax-no wpr-sticky-section-no wpr-column-slider-no wpr-equal-height-no e-con e-child\" data-id=\"e265448\" data-element_type=\"container\" data-e-type=\"container\">\n				<div class=\"elementor-element elementor-element-0022323 elementor-widget elementor-widget-heading\" data-id=\"0022323\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"heading.default\">\n				<div class=\"elementor-widget-container\">\n					<span class=\"elementor-heading-title elementor-size-default\">About Rental Power</span>				</div>\n				</div>\n				<div class=\"elementor-element elementor-element-dc4143e elementor-widget elementor-widget-heading\" data-id=\"dc4143e\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"heading.default\">\n				<div class=\"elementor-widget-container\">\n					<h1 class=\"elementor-heading-title elementor-size-default\">Reliable power, cooling &amp; support across the UAE</h1>				</div>\n				</div>\n				<div class=\"elementor-element elementor-element-fda1747 elementor-widget elementor-widget-text-editor\" data-id=\"fda1747\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p class=\"isSelectedEnd\">Rental Power provides reliable generator rental, chiller rental, AC rental, and temporary cooling solutions across the UAE. We support construction sites, commercial and industrial facilities, events, and emergency requirements with well-maintained equipment and practical rental options.</p><p>From short-term equipment requirements to long-term projects, our team helps you select, deliver, install, and support the right equipment for your site across Dubai, Abu Dhabi, Sharjah, Ajman, Ras Al Khaimah, and the wider UAE.</p>								</div>\n				</div>\n				<div class=\"elementor-element elementor-element-3229c2f elementor-align-left elementor-widget elementor-widget-elementskit-button\" data-id=\"3229c2f\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"elementskit-button.default\">\n				<div class=\"elementor-widget-container\">\n					<div class=\"ekit-wid-con\" >		<div class=\"ekit-btn-wraper\">\n							<a href=\"tel:+971%2056%20921%203754\" class=\"elementskit-btn  whitespace--normal\" id=\"\">\n					+971 56 921 3754				</a>\n					</div>\n        </div>				</div>\n				</div>\n				</div>\n		<div class=\"elementor-element elementor-element-74b3ec7 e-con-full e-flex wpr-particle-no wpr-jarallax-no wpr-parallax-no wpr-sticky-section-no wpr-column-slider-no wpr-equal-height-no e-con e-child\" data-id=\"74b3ec7\" data-element_type=\"container\" data-e-type=\"container\">\n				<div class=\"elementor-element elementor-element-bb5097d elementor-widget elementor-widget-image\" data-id=\"bb5097d\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"image.default\">\n				<div class=\"elementor-widget-container\">\n															<img fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"/storage/media/2026/07/rental-power-1024x683.webp\" class=\"attachment-large size-large wp-image-3520\" alt=\"rental power\" srcset=\"/storage/media/2026/07/rental-power-1024x683.webp 1024w, /storage/media/2026/07/rental-power-300x200.webp 300w, /storage/media/2026/07/rental-power-768x512.webp 768w, /storage/media/2026/07/rental-power-1536x1024.webp 1536w, http://lo