\r\n\r\n    const serviceField = document.querySelector(\'[name=\"service-needed\"]\');\r\n    const capacityField = document.getElementById(\'capacity-field\');\r\n    const capacityLabel = document.getElementById(\'capacity-label\');\r\n    const capacityInput = document.querySelector(\'[name=\"capacity-value\"]\');\r\n\r\n    if (!serviceField || !capacityField) return;\r\n\r\n    function updateCapacityField() {\r\n\r\n        const service = serviceField.value;\r\n\r\n        if (service === \'Generator Rental\') {\r\n\r\n            capacityField.style.display = \'block\';\r\n            capacityLabel.textContent = \'Estimated Generator Capacity (kVA)\';\r\n            capacityInput.placeholder = \'e.g. 250 kVA\';\r\n\r\n        } else if (service === \'Chiller Rental\') {\r\n\r\n            capacityField.style.display = \'block\';\r\n            capacityLabel.textContent = \'Required Chiller Capacity (Tons)\';\r\n            capacityInput.placeholder = \'e.g. 100 Tons\';\r\n\r\n        } else if (service === \'AC Rental\') {\r\n\r\n            capacityField.style.display = \'block\';\r\n            capacityLabel.textContent = \'Required AC Capacity\';\r\n            capacityInput.placeholder = \'e.g. 20 Ton\';\r\n\r\n        } else {\r\n\r\n            capacityField.style.display = \'none\';\r\n            capacityInput.value = \'\';\r\n        }\r\n    }\r\n\r\n    serviceField.addEventListener(\'change\', updateCapacityField);\r\n\r\n    updateCapacityField();\r\n});\r\n</script>				</div>\n				</div>\n				</div>\n					</div>\n				</div>\n		<div class=\"elementor-element elementor-element-e06166c e-con-full e-flex wpr-particle-no wpr-jarallax-no wpr-parallax-no wpr-sticky-section-no wpr-column-slider-no wpr-equal-height-no e-con e-parent\" data-id=\"e06166c\" data-element_type=\"container\" data-e-type=\"container\">\n				<div class=\"elementor-element elementor-element-7f9ca1b elementor-widget elementor-widget-google_maps\" data-id=\"7f9ca1b\" data-element